mapper.select:
select sceneId,sceneName,effStatus,startDate,endDate,remark,is_tmpl, dataStatus,sceneType,sceneType2,riskType,suitProduct, ftrName,belongInstitutionCode from (select distinct a.scene_id as sceneId, a.scene_name as sceneName, a.eff_status as effStatus, a.start_date as startDate, a.end_date as endDate, a.remark, a.is_tmpl as is_tmpl, a.Institution_Code belongInstitutionCode, nvl2((select t.scene_ftr_id from stt_scene_factor t where t.scene_id = a.scene_id and t.ftr_value is null and rownum < 2), '未准备', '已准备') as dataStatus, b.tips_value as sceneType, g.tips_value as sceneType2, c.tips_value as riskType, h.tips_value as suitProduct, I.FTRNAME AS FTRNAME from stt_scene a left join stt_scene_tips b on a.scene_id = b.scene_id and b.dict_code = 'SCENE_TYPE' and b.tips_value = #{sceneType, jdbcType=VARCHAR} left join stt_scene_tips g on a.scene_id = g.scene_id and g.dict_code = 'SCENE_TYPE2' and g.tips_value = #{sceneType2, jdbcType=VARCHAR} left join stt_scene_tips c on a.scene_id = c.scene_id and c.dict_code = 'RISK_TYPE' and c.tips_value = #{riskType, jdbcType=VARCHAR} left join stt_scene_tips h on a.scene_id = h.scene_id and h.dict_code = 'OPENMODE' and h.tips_value = #{suitProduct, jdbcType=VARCHAR} LEFT JOIN ( SELECT LISTAGG(ITEM_VALUE, ',') WITHIN GROUP(ORDER BY ITEM_CODE) over(PARTITION BY SCENE_ID) AS FTRNAME, SCENE_ID FROM (SELECT DISTINCT G2.ITEM_VALUE, G2.ITEM_CODE, G1.SCENE_ID FROM STT_SCENE_TIPS G1, SYS_DATADICT_LIST G2 WHERE G2.DICT_CODE = 'FTR_RSK_TYPE2' AND G2.ITEM_CODE = G1.TIPS_VALUE)) I ON A.SCENE_ID = I.SCENE_ID
join stt_scene_ftrtips d on a.scene_id = d.scene_id and d.dict_code = 'FTR_RSK_TYPE2' and d.param_value = #{ftrId, jdbcType=VARCHAR}
and a.scene_id = #{sceneIds[0], jdbcType=VARCHAR}
and a.scene_id in
#{item}
and a.scene_name = #{sceneNames[0], jdbcType=VARCHAR}
and a.scene_name in
#{item}
and a.eff_status = #{effStatus, jdbcType=VARCHAR} and a.start_date <= to_date(#{startDate, jdbcType=VARCHAR}, 'yyyy-MM-dd') and a.end_date >= to_date(#{endDate, jdbcType=VARCHAR}, 'yyyy-MM-dd') ) z
z.is_tmpl = #{isTmpl, jdbcType=VARCHAR} and z.riskType = #{riskType, jdbcType=VARCHAR} and z.sceneType = #{sceneType, jdbcType=VARCHAR} and z.sceneType2 = #{sceneType2, jdbcType=VARCHAR} and z.suitProduct = #{suitProduct, jdbcType=VARCHAR}
order by z.sceneId desc

